UPDATE lessons SET title='Year 7, Week 9, Lesson 3: Vocabulary from the novel', data=json_patch(data,'{"child_mission":"Novel vocabulary grows through context clues, word families and deliberate reuse in sentences about the book. Prefer precise words from the text when analysing (jetty, ration, curfew) over vague ones (stuff, things).","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nChoose two challenging words from your novel; write clue + original sentence for each.\n\nFEEDBACK\nStrong answer: Clues from text; sentences show accurate meaning.\n\nCHECK\nCopying dictionary definitions without being able to use the word.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nBuild a 10-word novel glossary with clue, definition in your words and a book-linked sentence each.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Novel vocabulary grows through context clues, word families and deliberate reuse in sentences about the book. Prefer precise words from the text when analysing (jetty, ration, curfew) over vague ones (stuff, things).","lesson_number":3,"lesson_role":"Language and vocabulary","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN4-ECB-01"],"parent_notes":"Parent: Marking guidance for the independent task: Build a 10-word novel glossary with clue, definition in your words and a book-linked sentence each. Acc